parameters.jsCode:
const execution = $json;
const lead = $('Find Stuck Leads').item.json;

const MAIN_WORKFLOW_ID = 'YOUR_MAIN_WORKFLOW_ID';

let action = 'skip';

const correctExecution =
  String(execution.id) === String(lead.execution_id);

const correctWorkflow =
  execution.workflowId === MAIN_WORKFLOW_ID;

if (correctExecution && correctWorkflow) {
  if (
    execution.status === 'success' &&
    execution.finished === true
  ) {
    action = 'check_completion';
  } else if (
    ['error', 'crashed', 'canceled'].includes(execution.status) &&
    execution.stoppedAt
  ) {
    action = 'recover';
  }
}

return {
  json: {
    lead_id: lead.lead_id,
    execution_id: String(lead.execution_id),
    execution_status: execution.status,
    workflow_id: execution.workflowId,
    action
  }
};

